<?php
require_once __DIR__ . "/config/database.php";
require_once __DIR__ . "/includes/content_helpers.php";
$conn->query("CREATE TABLE IF NOT EXISTS gallery_media (id INT AUTO_INCREMENT PRIMARY KEY,gallery_id INT NOT NULL,media_type ENUM('image','video','youtube') NOT NULL,media_path VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(gallery_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$id=(int)($_GET['id']??0);$st=$conn->prepare('SELECT id,title,image FROM gallery WHERE id=? LIMIT 1');$st->bind_param('i',$id);$st->execute();$item=$st->get_result()->fetch_assoc();if(!$item)http_response_code(404);$st=$conn->prepare('SELECT * FROM gallery_media WHERE gallery_id=? ORDER BY id DESC');$st->bind_param('i',$id);$st->execute();$media=$st->get_result();$rows=$media?$media->fetch_all(MYSQLI_ASSOC):[];
if($item && !$rows && !empty($item['image']))$rows[]=['media_type'=>'image','media_path'=>$item['image']];
?>
<!DOCTYPE html><html lang="id"><head><?php include __DIR__."/includes/head.php"; ?><title><?=htmlspecialchars($item['title']??'Gallery')?></title><link rel="stylesheet" href="assets/css/content-clickable.css"><style>.gallery-media-item{background:#f4f6f8;border-radius:14px;overflow:hidden;height:100%;padding:10px}.gallery-media-item img{width:100%;height:300px;object-fit:contain}.gallery-media-item video{width:100%;max-height:420px}.gallery-media-item iframe{width:100%;height:100%;min-height:280px;border:0}.gallery-media-item .ratio{--bs-aspect-ratio:56.25%}</style></head><body><?php include __DIR__."/includes/navbar.php"; ?><main class="section-padding"><div class="container"><a href="gallery.php" class="content-back-link">← Kembali ke Gallery</a><?php if(!$item):?><div class="alert alert-warning mt-3">Kategori galeri tidak ditemukan.</div><?php else:?><h1 class="content-detail-title mt-3"><?=htmlspecialchars($item['title'])?></h1><div class="row g-4 mt-2"><?php foreach($rows as $m):?><div class="col-md-6 col-lg-4"><div class="gallery-media-item"><?php if($m['media_type']==='youtube'):?><div class="ratio ratio-16x9"><iframe src="<?=htmlspecialchars($m['media_path'])?>" title="Video YouTube" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div><?php elseif($m['media_type']==='video'):?><video controls preload="metadata"><source src="<?=htmlspecialchars('uploads/gallery/'.basename($m['media_path']))?>">Browser tidak mendukung video.</video><?php else:$src=contentImageUrl($m['media_path'],'uploads/gallery');?><a href="<?=htmlspecialchars($src)?>" target="_blank" rel="noopener"><img src="<?=htmlspecialchars($src)?>" alt="<?=htmlspecialchars($item['title'])?>" loading="lazy"></a><?php endif;?></div></div><?php endforeach;?></div><?php endif;?></div></main><?php include __DIR__."/includes/footer.php"; ?></body></html>
